    {open&&<div className="hero-picker" id="hero-picker" role="group" aria-label="Chọn sức mạnh">
      <div className="hero-picker-heading"><span><Sparkles size={14}/> SỨC MẠNH AVENGERS</span><button onClick={()=>{setOpen(false);toggle.current?.focus();}} aria-label="Đóng chọn sức mạnh"><X size={16}/></button></div>
      <div className="hero-options">{HEROES.map(option=><button key={option.id} className={`hero-option ${option.id===powers.hero?'selected':''} ${option.id==='none'?'hero-normal':''}`} disabled={selectionDisabled} aria-pressed={option.id===powers.hero} onClick={()=>choose(option.id)} style={{'--option-color':option.color} as CSSProperties}><span className="hero-option-icon"><HeroIcon hero={option.id} size={21}/></span><span className="hero-option-copy"><b>{option.name}</b><small>{option.id==='none'?'Dạo phố, làm nhiệm vụ như thường':option.description}</small>{option.id!=='none'&&<em>{option.powerName} · hồi {option.cooldown}s</em>}</span>{option.id===powers.hero&&<Check size={14} className="hero-option-check"/>}</button>)}</div>
      <p><kbd>J</kbd> Đổi anh hùng <span>·</span> <kbd>K</kbd> Dùng sức mạnh{selectionDisabled&&<strong>{selectionReason}</strong>}</p>
    </div>}
    <button ref={toggle} className="hero-toggle" onClick={()=>setOpen(value=>!value)} aria-expanded={open} aria-controls="hero-picker" aria-label={`Chọn sức mạnh. Hiện tại: ${hero.name}`}><span className="hero-current-icon"><HeroIcon hero={powers.hero}/></span><span><small>{hasPower?'ANH HÙNG CỦA BẠN':'THỬ SỨC MẠNH'}</small><b>{hasPower?hero.name:'Chọn anh hùng'}</b></span><ChevronsUpDown size={14}/><kbd>J</kbd></button>
    {hasPower&&<><button className={`power-cast ${cooling?'cooling':''}`} onClick={onUse} disabled={unavailable||cooling} aria-label={`${hero.powerName}: ${cooldownLabel}`} title={unavailable?reason:hero.description}><i className="power-cooldown-fill" style={{width:`${cooling?Math.min(100,powers.cooldown/Math.max(.1,powers.cooldownTotal)*100):0}%`}}/><span><HeroIcon hero={powers.hero} size={14}/><b>{hero.powerName}</b><kbd>K</kbd></span><small>{cooldownLabel}</small></button><div className={`flight-controls ${powers.hero==='ironman'?'':'energy-only'}`}>{powers.hero==='ironman'&&<button onClick={onFlight} disabled={disabled||powers.blocked||(!powers.flying&&powers.energy<15)} aria-pressed={powers.flying} aria-label={powers.flying?'Hạ cánh':'Bật bay Iron Man'} title={disabled?reason:'G · Bật hoặc tắt bay'}><Rocket size={12}/><span>{powers.flying?'Hạ cánh':'Cất cánh'}</span><kbd>G</kbd></button>}<div className="power-energy" role="meter" aria-label="Năng lượng sức mạnh" aria-valuemin={0} aria-valuemax={100} aria-valuenow={Math.round(powers.energy)}><Zap size={10} aria-hidden="true"/><span><i style={{width:`${Math.max(0,Math.min(100,powers.energy))}%`}}/></span><small>{Math.round(powers.energy)}%</small></div></div></>}
