useEffect(()=>{const shortcuts=(event:KeyboardEvent)=>{const target=event.target;if(target instanceof HTMLElement&&target.closest('input,textarea,select,[contenteditable="true"]'))return;if(event.key==='Escape'){setMissionsOpen(false);setMapOpen(false);setStoreOpen(false);setBikeShopOpen(false);setHospitalOpen(false);setVenueOpen(null);setHelp(false);setSettingsOpen(false);if(menuView)closeCounter();}else if(active&&!help&&!storeOpen&&!bikeShopOpen&&!hospitalOpen&&!venueOpen&&!bagOpen&&!menuView&&!event.repeat&&!event.ctrlKey&&!event.metaKey&&!event.altKey){if(event.code==='KeyM'||event.key.toLowerCase()==='m'){event.preventDefault();setSettingsOpen(false);setMapOpen(false);setMissionsOpen(value=>!value);}else if(event.code==='KeyN'||event.key.toLowerCase()==='n'){event.preventDefault();setSettingsOpen(false);setMissionsOpen(false);if(!mapOpen)setMapHeading(game.current?.getState().angle??0);setMapOpen(!mapOpen);}}};window.addEventListener('keydown',shortcuts);return()=>window.removeEventListener('keydown',shortcuts);},[active,help,storeOpen,bikeShopOpen,hospitalOpen,venueOpen,bagOpen,mapOpen,menuView]);
useEffect(()=>{sessionRef.current=session;},[session]);
